package top.monitorglobal.tv;
import org.junit.Test;import static org.junit.Assert.*;import java.time.*;import java.util.*;
public class InfraredPlanTest {
 long now=Instant.parse("2026-11-04T16:00:00Z").toEpochMilli();
 @Test public void timestampsMustBeAdvertisedRecentSubdailyAndBounded(){String xml="<Domains><Domain>2026-11-04T12:00:00Z/2026-11-04T15:30:00Z/PT10M</Domain></Domains>";List<Long> frames=InfraredPlan.frames(xml,now);assertEquals(6,frames.size());assertEquals(Instant.parse("2026-11-04T15:30:00Z").toEpochMilli(),(long)frames.get(5));for(String bad:new String[]{"<Exception/>",xml.replace("2026-11-04","2026-11-01"),xml.replace("15:30","17:30"),xml.replace("PT10M","P1D")})assertTrue(InfraredPlan.frames(bad,now).isEmpty());}
 @Test public void projectionIsMercatorAndMetadataKeepsTimeDelimiters(){assertTrue(InfraredPlan.domains(now).contains("TIME=2026-11-04T12:00:00Z/2026-11-04T16:00:00Z"));InfraredPlan.Scope s=InfraredPlan.SOUTHEAST;assertEquals(0,s.x(s.west),.001);assertEquals(InfraredPlan.WIDTH,s.x(s.east),.001);assertEquals(0,s.y(s.north),.001);assertEquals(s.height,s.y(s.south),.001);assertTrue(s.y(-23.55)>0);assertTrue(InfraredPlan.image(s,now).contains("SRS=EPSG:3857"));assertTrue(InfraredPlan.image(s,now).contains("TIME=2026-11-04T16:00:00Z"));}
 @Test public void labelsUseBrazilianDateAndExposeAge(){String text=InfraredPlan.timing(now-35*60000,now);assertTrue(text.contains("04/11/2026"));assertTrue(text.contains("12:25 BRT"));assertTrue(text.contains("há 35 min"));assertTrue(text.contains("DEFASADA"));assertTrue(InfraredPlan.timing(now-120*60000,now).contains("IMAGEM EXPIRADA"));}
 @Test public void sourceOlderThanNinetyMinutesIsNotPresented(){assertTrue(InfraredPlan.frames("<Domains><Domain>2026-11-04T13:00:00Z/2026-11-04T14:20:00Z/PT10M</Domain></Domains>",now).isEmpty());assertEquals(90*60000L,InfraredPlan.MAX_AGE);assertEquals(1024,InfraredPlan.WIDTH);}
}
